entries[140336] = { ["name"] = "Brulfaustgötze", ["text"] = "[Broken Isles]\nWird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört einen Brulfaustgötzen zu Füßen des Zaubernden, der ihn in die Luft schleudert... aufs Heftigste. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[140337] = { ["name"] = "Importiertes zähes Stockfleisch", ["text"] = "Benutzen: Stellt im Verlauf von 18 Sek. ( 38 * 18 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Die übermäßige Verwendung von Salz macht dieses Fleisch sehr beliebt in den kleinen ländlichen Städten Azeroths.\"\nVerkaufspreis:" }
entries[140338] = { ["name"] = "Manaumwickelte Pastete aus Geiferzahnleber", ["text"] = "Benutzen: Stellt im Verlauf von 21 Sek. ( 38 * 21 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 1 Ausdauer und Vielseitigkeit.\n\"Diese Pastete wurde in einem Land namens Westfall hausgemacht und zur Frischhaltung mit Mana umwickelt.\"\nVerkaufspreis:" }
entries[140339] = { ["name"] = "Hormonfreier Alteraclochkäse", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 375 * 30 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Der Verkäufer hat behauptet, dies wäre ein Lieblingsgericht am berühmtem Hof von Alterac gewesen.\"\nVerkaufspreis:" }
entries[140340] = { ["name"] = "Flasche Sprudelwasser", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 917 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Irgendwie haben sie es geschafft, das Wasser ohne die Nutzung von Magie mit Blasen zu versetzen...\"\nVerkaufspreis:" }
entries[140341] = { ["name"] = "Wilder pochierter Kaiserlachs", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 1161 * 30 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Aus den nördlichen Gewässern.\"\nVerkaufspreis:" }
entries[140342] = { ["name"] = "Magere Rippchen der Mok'Nathal", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 355 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 30 Min. lang 3 Ausdauer und Vielseitigkeit.\n\"Dieses große Tier stammt angeblich aus einer anderen Welt!\"\nVerkaufspreis:" }
entries[140343] = { ["name"] = "Exotisch ekliger Gaumenschmaus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 10) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 15 erhöht.\n\nIrgendetwas scheint allerdings nicht zu stimmen...\n\"Ein Gericht für die absolut Anspruchsvollsten, aus einem nebelverhüllten Land.\"\nVerkaufspreis:" }
entries[140344] = { ["name"] = "Eingemachtes Solei", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 910 * 30 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Der Händler, der mir dies verkauft hat, sagte, es wäre ein populäres Gericht des berühmten und exotischen Lokals 'Zum Grimmigen Säufer'.\"\nVerkaufspreis:" }
entries[140346] = { ["name"] = "Fläschchen Arkflamme", ["text"] = "Questgegenstand\nBenutzen: Wirft ein Fläschchen Arkflamme auf ein Vergnügungsschiff in der Nähe. (5 Sek. Abklingzeit)" }
entries[140347] = { ["name"] = "Geisterbeeren", ["text"] = "Benutzen: Stellt 2000 Mana wieder her. (5 Min Abklingzeit)" }
entries[140348] = { ["name"] = "Boshafter Kriegsschreiter", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegsschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Exklusiv, stilvoll und tödlich.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
entries[140349] = { ["name"] = "Unbenutzter arkaner Zauberschutz", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[140350] = { ["name"] = "Boshafter Kriegselekk", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren boshaften Kriegselekk oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sehr beliebt unter Kriegern der Exodar.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[140351] = { ["name"] = "Sonnenfrucht", ["text"] = "Benutzen: Stellt 6000 Gesundheit wieder her. (5 Min Abklingzeit)" }
entries[140352] = { ["name"] = "Traumbeeren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt 5 Sek. lang pro Sekunde 20% Eurer Gesundheit und Eures Manas wieder her.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden." }
entries[140353] = { ["name"] = "Boshaftes gilnearisches Kriegsross", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein boshaftes gilnearisches Kriegsross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Geboren, aufgezogen und für den Kampf geprüft in Gilneas.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[140354] = { ["name"] = "Boshaftes Kriegstrike", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer boshaftes Kriegstrike oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die verheerendste Technologie, die käuflich auf dem Markt zu haben ist.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
entries[140355] = { ["name"] = "Nahrhafter Apfel", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 7500 / 5 * 20) Gesundheit und ( 3750 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Mit Komplimenten von Apfelzweig in Dalaran.\"\nVerkaufspreis:" }
entries[140356] = { ["name"] = "Dämonische Kritzeleien", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Selbst für andere Dämonen wäre dieses Gekritzel vollkommen unleserlich.\"" }
entries[140357] = { ["name"] = "Teufelslavastein", ["text"] = "Wird beim Aufheben gebunden\n\"Er ist immer ein wenig warm.\"\nVerkaufspreis:" }
entries[140358] = { ["name"] = "Schnalle einer Eredarrüstung", ["text"] = "Wird beim Aufheben gebunden\n\"Bis vor Kurzem hat jemand sie offenbar sorgfältig gepflegt.\"\nVerkaufspreis:" }
entries[140359] = { ["name"] = "Verdunkeltes Auge", ["text"] = "Wird beim Aufheben gebunden\n\"Einem Auge von Zoth ließ sich nicht aus dem Weg gehen. Also musste eine andere Lösung her.\"\nVerkaufspreis:" }
entries[140360] = { ["name"] = "Felswurmstachel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Nicht sonderlich spitz, aber hart genug, um Stein zu durchdringen.\"\nVerkaufspreis:" }
entries[140361] = { ["name"] = "Pulsierender Runenstein", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Brocken enthält zwar keine Magie mehr, summt aber dafür recht schön.\"\nVerkaufspreis:" }
entries[140362] = { ["name"] = "Staub aus den Schattenlanden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Dieser Staub besitzt zwar keinerlei Macht, wirkt aber, als käme er nicht von dieser Welt.\"" }
entries[140363] = { ["name"] = "Taschenteufelskondensator", ["text"] = "Spielzeug\nBenutzen: Beschwört einen kleinen Teufelskondensator, der die Verderbnis der Legion verbreiten wird. (30 Min Abklingzeit)\n\"Es ist nicht empfehlenswert, dieses Ding wirklich in Eurer Tasche zu lassen.\"\nVerkaufspreis:" }
entries[140364] = { ["name"] = "Frostwyrmknochenfragment", ["text"] = "Wird beim Aufheben gebunden\n\"Es summt noch vor Macht und muss beim Flug über Eiskrone abgesplittert sein.\"\nVerkaufspreis:" }
entries[140365] = { ["name"] = "Getrocknete Lilie von Stratholme", ["text"] = "Wird beim Aufheben gebunden\n\"Einst blühten sie in ganz Lordaeron. Jemand liebte sie wohl so sehr, dass er ein paar Blüten in einem Buch getrocknet hat.\"\nVerkaufspreis:" }
entries[140366] = { ["name"] = "Scharlachrotes Gesangbuch", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Sammlung von Hymnen an das Licht, zusammengetragen und arrangiert durch den Scharlachroten Kreuzzug.\"\nVerkaufspreis:" }
entries[140367] = { ["name"] = "Ramponiertes Notenblatt", ["text"] = "Wird beim Aufheben gebunden\n\"Echte Musikliebhaber erkennen hieraus die Vertonung von 'Romulo und Julianne'.\"\nVerkaufspreis:" }
entries[140368] = { ["name"] = "Angelaufener Verlobungsring", ["text"] = "Wird beim Aufheben gebunden\n\"Der Tod nimmt einem wirklich alles.\"\nVerkaufspreis:" }
entries[140369] = { ["name"] = "Hingekritzeltes Rezept", ["text"] = "Wird beim Aufheben gebunden\n\"Das scheint ein Rezept für einen erfrischenden Minzcocktail zu sein. Oder für eine Seuche, die alles Leben auf Azeroth auslöscht. Vielleicht auch beides.\"\nVerkaufspreis:" }
entries[140370] = { ["name"] = "Bernsteinsplitter", ["text"] = "Wird beim Aufheben gebunden\n\"Ein winziges Insekt ist darin gefangen.\"\nVerkaufspreis:" }
entries[140371] = { ["name"] = "Brief von Exarch Maladaar", ["text"] = "Wird beim Aufheben gebunden\n\"Der Brief beginnt mit den Worten: 'Liebste Nyami, leider muss ich Euch mitteilen, dass Euer Sohn unter denen ist, die von den Orcs entführt wurden. Wir befürchten das Schlimmste.'\"\nVerkaufspreis:" }
entries[140372] = { ["name"] = "Uralter Konstrukteursmanipulator", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[140373] = { ["name"] = "Verzierter Stiefelriemen", ["text"] = "Wird beim Aufheben gebunden\n\"Er ist anscheinend irgendwann von einem wirklich guten Paar Stiefel abgerissen.\"\nVerkaufspreis:" }
entries[140374] = { ["name"] = "Gezackter Worgenfangzahn", ["text"] = "Wird beim Aufheben gebunden\n\"Niemand weiß, woher er stammt, aber er ist groß und furchteinflößend.\"\nVerkaufspreis:" }
entries[140375] = { ["name"] = "Benutzte Teufelsklingen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Der einstige Besitzer braucht sie wohl nicht mehr.\"\nVerkaufspreis:" }
entries[140376] = { ["name"] = "Mardum-kalibrierter Ausgleicher", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Angepasst an die einzigartigen Lebensumstände auf Mardum.\"" }
entries[140377] = { ["name"] = "Zerbrochenes Medaillon von Karabor", ["text"] = "Wird beim Aufheben gebunden\n\"Es gehörte einst einem Priester von Karabor und hat wohl schon bessere Zeiten erlebt.\"\nVerkaufspreis:" }
entries[140378] = { ["name"] = "Ariana Feuerherz", ["text"] = "Questgegenstand\n\"Gestattet Euch, Adepten der Illidari zu rekrutieren.\"" }
entries[140379] = { ["name"] = "Geborstene Klinge einer Wächterinnengleve", ["text"] = "Wird beim Aufheben gebunden\n\"Um diese Klinge zu brechen, war viel Kraft notwendig.\"\nVerkaufspreis:" }
entries[140380] = { ["name"] = "Schwanzfeder von Windstoß", ["text"] = "Wird beim Aufheben gebunden\n\"Das Gefieder ist leuchtend blau und violett schattiert.\"\nVerkaufspreis:" }
entries[140381] = { ["name"] = "Ring und Finger des Jarls von Jandvik", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Ring pulsiert mit uralter Macht und sitzt fest auf dem Stumpf.\"\nVerkaufspreis:" }
entries[140382] = { ["name"] = "Winzige Kriegstrommel", ["text"] = "Wird beim Aufheben gebunden\n\"Viel zu klein für ausgewachsene Teufelstotems.\"\nVerkaufspreis:" }
entries[140383] = { ["name"] = "Leuchtender Höhlenpilz", ["text"] = "Wird beim Aufheben gebunden\n\"Daran hat schon etwas geknabbert.\"\nVerkaufspreis:" }
entries[140384] = { ["name"] = "Szepter des Hofs von Azshara", ["text"] = "Wird beim Aufheben gebunden\n\"Wurde Beratern der Königin überlassen.\"\nVerkaufspreis:" }
entries[140385] = { ["name"] = "Handzettel der Legion", ["text"] = "Wird beim Aufheben gebunden\n\"Er wurde so oft gefaltet und wieder geöffnet, dass die Schrift kaum noch lesbar ist.\"\nVerkaufspreis:" }
entries[140386] = { ["name"] = "Schattenkugel des Inquisitors", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[140387] = { ["name"] = "Edelstein für Armschienen", ["text"] = "Wird beim Aufheben gebunden\n\"Selbst Wichtelmütter wissen geschmackvolle Accessoires zu schätzen.\"\nVerkaufspreis:" }
entries[140388] = { ["name"] = "Falanaaredelstein", ["text"] = "Wird beim Aufheben gebunden\n\"Glänzend und hell. Oreth behielt diesen wertvollen Stein immer in seiner Nähe.\"\nVerkaufspreis:" }
entries[140389] = { ["name"] = "Versteinerte Flamme", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Stein flackert ab und zu, als würde sein Inneres noch brennen.\"\nVerkaufspreis:" }
