entries[140393] = { ["name"] = "Repentias Peitsche", ["text"] = "Wird beim Aufheben gebunden\n\"Durch regelmäßigen Gebrauch stark abgenutzt.\"\nVerkaufspreis:" }
entries[140394] = { ["name"] = "Dornenstielwiderhaken", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt sofort tödliche Dornenranken im Zielbereich wachsen, die alle Gegner innerhalb von 8 Metern bewegungsunfähig machen und ihnen 20 Sek. lang alle 1 Sek. (100% der Zaubermacht + 100% der Angriffskraft) Naturschaden zufügen.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden." }
entries[140395] = { ["name"] = "Elegante Ermittlerbrille", ["text"] = "Questgegenstand\nEinzigartig\nKopf\nAnlegen: Tragt diese außergewöhnlich elegante Ermittlerbrille, um Amber Kearnens Blutspur zu folgen." }
