entries[140399] = { ["name"] = "Gelbes Or'ligaiei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewinnt 75 uraltes Mana.\n\"Diese vom Kunsthandwerker Or'ligai für die Hohe Magistrix erschaffenen Eier sind bei der Lieferung zum Palast verloren gegangen.\"" }
entries[140400] = { ["name"] = "Perfekte Traumhainblüte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Intelligenz]\nErhöht Eure Tempowertung um + 7.\nKlassen: Druide\nAnlegen: Die perfekte Traumhainblüte erhöht Eure Bewegungsgeschwindigkeit um 20%.\n\nKann nur auf den Verheerten Inseln und Argus verwendet werden.\n\"Die Blütenblätter sind alle perfekt erhalten.\"\nVerkaufspreis:" }
entries[140401] = { ["name"] = "Blaues Or'ligaiei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewinnt 75 uraltes Mana.\n\"Diese vom Kunsthandwerker Or'ligai für die Hohe Magistrix erschaffenen Eier sind bei der Lieferung zum Palast verloren gegangen.\"" }
entries[140402] = { ["name"] = "Grünes Or'ligaiei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewinnt 75 uraltes Mana.\n\"Zwickzange dachte, dass er bereit wäre, dieses Ei zu beschützen.\"" }
