entries[140409] = { ["name"] = "Foliant des dimensionalen Bewusstseins", ["text"] = "Wird beim Aufheben gebunden\n\"Es war klug von Euch, dieses Buch mitzunehmen, denn es hat in den Jahren im Arkus massenhaft Wissen angesammelt.\"\nVerkaufspreis:" }
