entries[140493] = { ["name"] = "Adeptenleitfaden für Dimensionsreisen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teleportiert zu einem abgestimmten Leylinienpunkt auf den Verheerten Inseln. (4 Std. Abklingzeit)\n\"Mit diesem Leitfaden für Fortgeschrittene könnt Ihr mehr Leylinien der Verheerten Inseln nutzen.\"\nVerkaufspreis:" }
entries[140494] = { ["name"] = "Eredarschwanzmanschette", ["text"] = "Wird beim Aufheben gebunden\n\"Je verzierter die Manschette, desto mehr Ansehen genießt ihr Träger.\"\nVerkaufspreis:" }
entries[140495] = { ["name"] = "Zerrissene Einladung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eindeutig eine Einladung zu einem exklusiven Ereignis der adligen Nachtgeborenen.\"" }
entries[140496] = { ["name"] = "Einladung zur Fuchsjagd", ["text"] = "Questgegenstand\n\"Weitere Hinweise auf des Rätsels Lösung.\"" }
entries[140497] = { ["name"] = "Bündel winziger Speere", ["text"] = "Wird beim Aufheben gebunden\n\"Einzeln betrachtet ist jeder von ihnen so gefährlich wie eine Nähnadel. Aber ein paar Dutzend davon könnten schweren Schaden anrichten.\"\nVerkaufspreis:" }
entries[140498] = { ["name"] = "Notiz eines Verehrers der Legion", ["text"] = "Wird beim Aufheben gebunden\n\"Im Verlauf der verborgenen Mission hat diese Nachricht voller bewundernder Worte ihren Besitzer gewechselt.\"\nVerkaufspreis:" }
entries[140499] = { ["name"] = "Seltsam gefärbter Teufelsstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Noch immer warm.\"" }
entries[140500] = { ["name"] = "Mechanischer Holzextraktor", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man den mechanischen Holzextraktor fliegt. Das ist ein Flugreittier.\nSteigt in einen mechanischen Holzextraktor, wodurch Ihr sehr schnell fliegen könnt. Die Klauen sind überraschend präzise und können von Kräuterkundigen zum Kräuterpflücken verwendet werden. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Jepetto hat es vielleicht etwas übertrieben...\"\nErfolg:\nLasst die anderen auch mal spielen\nKategorie:\nSpielzeugkiste" }
entries[140501] = { ["name"] = "Veraltete Geheiminformationen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Einst wären diese Informationen von entscheidender Bedeutung gewesen, aber wegen eines bedauerlichen Verfahrensfehlers sind sie jetzt nutzlos.\"" }
entries[140502] = { ["name"] = "Zerlumpte Augenklappe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Der ehemalige Besitzer braucht sie nicht mehr.\"\nVerkaufspreis:" }
entries[140503] = { ["name"] = "Leere Aufgabenliste", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn dieses Papier in der Sonne gelassen wird, erscheint eine geheime Schrift.\"\nVerkaufspreis:" }
entries[140504] = { ["name"] = "Ankerseil der Kvaldir", ["text"] = "Wird beim Aufheben gebunden\n\"Schwer, krude und bedeckt mit diversen Meeresbewohnern.\"\nVerkaufspreis:" }
