entries[140507] = { ["name"] = "Unbeschrifteter Trank", ["text"] = "Wird beim Aufheben gebunden\n\"Prost! Oder lieber doch nicht.\"\nVerkaufspreis:" }
entries[140508] = { ["name"] = "Konstrukteurring der Nachtgeborenen", ["text"] = "Wird beim Aufheben gebunden\n\"Vollständig frei von Magie, glitzert aber sogar, wenn kein Licht darauf fällt.\"\nVerkaufspreis:" }
entries[140509] = { ["name"] = "Dämonische Kritzelzeichnung", ["text"] = "Wird beim Aufheben gebunden\n\"Sieht aus, als wollte ein niederer Dämon eine Landschaftsskizze anfertigen. Vielleicht ist es abstrakte Kunst?\"\nVerkaufspreis:" }
entries[140510] = { ["name"] = "Eisenschlüssel aus der Rabenwehr", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr könnt kein Schloss finden, in das er passt.\"\nVerkaufspreis:" }
entries[140511] = { ["name"] = "Seelenfessel", ["text"] = "Wird beim Aufheben gebunden\n\"Was auch immer diese Fessel einst gefangen hielt, ist längst verschwunden.\"\nVerkaufspreis:" }
entries[140512] = { ["name"] = "Übergroßer Trinkbecher", ["text"] = "Wird beim Aufheben gebunden\n\"Er ist selbst nach den Maßstäben der Vrykul dreimal so groß wie normal und leuchtet, als wäre er nicht von dieser Welt.\"\nVerkaufspreis:" }
entries[140513] = { ["name"] = "Belobigungsabzeichen des Schreckenslords", ["text"] = "Wird beim Aufheben gebunden\n\"Für schändliche Taten, die von der Legion auf anderen Welten begangen wurden.\"\nVerkaufspreis:" }
entries[140514] = { ["name"] = "Phiole der Luft", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht dem Charakter eine große Menge Erfahrung. Funktioniert nicht bei Spielercharakteren über Stufe 49.\n\"Sieht aus, als wäre es leer, doch ist es das wirklich? Kann irgendetwas jemals wirklich leer sein?\"" }
entries[140515] = { ["name"] = "Geschenk von Al'Akir", ["text"] = "Wird beim Aufheben gebunden\n\"Für die jahrelange Treue von Neblon. Niemand weiß, wo der Leutnant es aufbewahrt hat.\"\nVerkaufspreis:" }
entries[140516] = { ["name"] = "Elementararmschienen", ["text"] = "Wird beim Aufheben gebunden\n\"Rein dekorativ.\"\nVerkaufspreis:" }
entries[140517] = { ["name"] = "Ruhm des Ordens", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[140518] = { ["name"] = "Blitz in der Flasche", ["text"] = "Wird beim Aufheben gebunden\n\"Auf dem Etikett steht: 'Vorsicht! Nicht bei schönem Wetter öffnen.'\"\nVerkaufspreis:" }
entries[140519] = { ["name"] = "Flüsterndes Totem", ["text"] = "Wird beim Aufheben gebunden\n\"Das könnte ein Totem der Luft sein, vielleicht ist es aber auch verflucht.\"\nVerkaufspreis:" }
