entries[140651] = { ["name"] = "Muster: Gravurschuppenhalsberge", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Gravurschuppenhalsberge herstellt.\nStellt eine Gravurschuppenhalsberge her.\nBenötigt Lederverarbeitung der Verheerten Inseln (1)\nVerkaufspreis:\nGravurschuppenhalsberge\nWird beim Anlegen gebunden\nBrust Kette\n12 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 165 / 165\nVerkaufspreis:\nBenötigt Sturmschuppe (180), Leysteinerz (80), Teufelsbalg (2)" }
entries[140652] = { ["name"] = "Saat des Solarfeuers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Kombiniert die Saat des Solarfeuers mit einem reinen Tropfen von Shaladrassils Harz, um eine seltene Sonnenblüte zu erschaffen.\nBenötigt Die Traumweber\n- Ehrfürchtig\n\"Ein hell schimmernder Samen aus den Tiefen des Smaragdgrünen Traums. Die Traumweber konnten nie herausfinden, wie man ihn erblühen lässt.\"\nVerkaufspreis:" }
entries[140653] = { ["name"] = "Reiner Tropfen von Shaladrassils Harz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nBenutzen: Kombiniert die Saat des Solarfeuers mit einem reinen Tropfen von Shaladrassils Harz, um eine seltene Sonnenblüte zu erschaffen.\n\"Ein einzelner Tropfen leuchtenden Harzes, das angeblich sogar in so gut wie toten Überresten den Funken des Lebens neu entfachen kann.\"" }
entries[140654] = { ["name"] = "Modriger Balg von Nythendra", ["text"] = "Questgegenstand\n\"Dieser Balg wurde fast vollständig von Insekten zerfressen.\"" }
entries[140655] = { ["name"] = "Klotz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört für 10 Min. ein unvollendetes Totem. (10 Min Abklingzeit)\nBenötigt Der Hochbergstamm\n- Respektvoll\n\"Groß und schwer und aus Holz.\"\nVerkaufspreis:" }
entries[140656] = { ["name"] = "Rute des Aufgestiegenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Kombiniert die Krone der Lichtgeborenen mit der Rute des Aufgestiegenen, um den Stab der Lichtgeborenen zu erschaffen.\nBenötigt Valarjar\n- Ehrfürchtig\n\"Ein exquisiter Stab, der für einen längst vergessenen Vrykulmystiker geschaffen wurde, um große Macht zu kanalisieren. Ohne das richtige Kopfstück ist der Stab jedoch inaktiv.\"\nVerkaufspreis:" }
entries[140657] = { ["name"] = "Krone der Lichtgeborenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nBenutzen: Kombiniert die Krone der Lichtgeborenen mit der Rute des Aufgestiegenen, um den Stab der Lichtgeborenen zu erschaffen.\n\"Ein verziertes Kopfstück, erfüllt von pulsierender heiliger Kraft. Mit dem richtigen Instrument, um seine Macht zu kanalisieren, wäre dies eine mächtige Waffe des Lichts.\"" }
entries[140658] = { ["name"] = "Schädel von Nithogg", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Fügt den Griff des Gottkönigs mit dem Schädel von Shar'thos und dem Schädel von Nithogg zusammen, um die Drachenschlächter zu erschaffen.\n\"Ein gewaltiger Drachenschädel, in dem Nithoggs donnernde Macht immer noch knistert.\"" }
entries[140659] = { ["name"] = "Schädel von Shar'thos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Fügt den Griff des Gottkönigs mit dem Schädel von Shar'thos und dem Schädel von Nithogg zusammen, um die Drachenschlächter zu erschaffen.\n\"Ein gewaltiger Drachenschädel, in dem Shar'thos' alptraumhafte Macht immer noch vibriert.\"" }
entries[140660] = { ["name"] = "Griff des Gottkönigs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nBenutzen: Fügt den Griff des Gottkönigs mit dem Schädel von Shar'thos und dem Schädel von Nithogg zusammen, um die Drachenschlächter zu erschaffen.\n\"Ein gewaltiger Griff für eine Großaxt, aber ohne Axtklinge. Das Holz ist mit mystischen Vrykulrunen verziert. Der Griff ist eindeutig für Vrykulkrieger gemacht, aber er ist so segmentiert, dass man ihn in Schäfte für zwei Äxte teilen könnte...\"" }
