entries[140789] = { ["name"] = "Animiertes Exoskelett", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Ausdauer\nBenutzen: Verringert für 15 Sek. sämtlichen erlittenen Schaden um 30%, bis insgesamt [ 248 * (1 + Vielseitigkeit)] Schaden verhindert wurden. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[140790] = { ["name"] = "Klaue des kristallinen Skorpiden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\nAnlegen: Eure Angriffe haben eine Chance, eine Schaden verursachende Schockwelle auszulösen, die Gegnern vor Euch 34 körperlichen Schaden zufügt.\nVerkaufspreis:" }
entries[140791] = { ["name"] = "Königliches Dolchheft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Absorbiert bis zu 6587 Schaden eines Angriffs, der Euch töten würde. Wenn dieser Effekt auftritt, werdet Ihr sofort um 178 Gesundheit geheilt und erleidet danach im Verlauf von 10 Sek. den gesamten verhinderten Schaden. Dies kann nur einmal alle 6 Min. geschehen.\n\"Sand rieselt aus der gesprungenen Glaskugel am Ende des Griffs.\"\nVerkaufspreis:" }
entries[140792] = { ["name"] = "Unstetes Metronom", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Schadenszauber haben eine Chance, Euch 12 Sek. lang 4 Tempo zu gewähren. Dieser Effekt ist bis zu 5-mal stapelbar. Die einzelnen Stapel erneuern nicht die Effektdauer.\nVerkaufspreis:" }
entries[140793] = { ["name"] = "Perfekt erhaltener Kuchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Erschafft für 20 Sek. ein magisches Festmahl. Bis zu 5 Verbündete, die am Festmahl teilnehmen, absorbieren 12 Sek. lang 179 Schaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[140794] = { ["name"] = "Finger des Arkanogolems", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\nAnlegen: Eure Nahkampfangriffe haben eine Chance, alle Gegner vor Euch zu zerfetzen und ihnen 14 Arkanschaden zuzufügen.\nVerkaufspreis:" }
entries[140795] = { ["name"] = "Aluriels Spiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Eure Heilzauber haben eine Chance, dem Ziel 'Gelassenheit des Nachtbrunnens' zu gewähren, die im Verlauf von 12 Sek. 60 Gesundheit regeneriert. Das Heilen eines Ziels, das von 'Gelassenheit des Nachtbrunnens' betroffen ist, kann eine Detonation auslösen, die Verbündete in der Nähe um 10 Gesundheit heilt.\nVerkaufspreis:" }
entries[140796] = { ["name"] = "Verschlungene Elementarfokusse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Euch für 20 Sek. eine Feuer-, Frost- oder Arkanverzauberung zu gewähren.\nVerkaufspreis:" }
entries[140797] = { ["name"] = "Eckzahn von Tichondrius", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nBenutzen: Gewinnt für 12 Sek. 28 Lebensraub. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[140798] = { ["name"] = "Ikone des Verrottens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, einen Aasschwarm zu entfesseln, der alle Gegner in einer Linie vor Euch infiziert und ihnen im Verlauf von 8 Sek. ( 21 * 4) Schattenschaden zufügt.\nVerkaufspreis:" }
entries[140799] = { ["name"] = "Macht von Krosus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Stärke\nBenutzen: Entfesselt ein kolossales Schmettern, das immer kritisch trifft und 119 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. Wenn Ihr weniger als 3 Ziele trefft, wird die Abklingzeit der Fähigkeit um 15 Sek. verringert. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[140800] = { ["name"] = "Pharameres verbotenes Grimoire", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Entsendet eine Sphäre der Zerstörung zur Position Eures Ziels in mindestens 10 Metern Entfernung, die nach 4 Sek. allen Gegnern innerhalb von 20 Metern 137 Schattenschaden zufügt. Ziele, die sich näher an der Explosion befinden, erleiden mehr Schaden. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[140801] = { ["name"] = "Zorn des brennenden Himmels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, an der Position Eures Ziels einen Solarkollaps hervorzurufen, der nach 3 Sek. Gegnern in der Nähe 63 Feuerschaden zufügt. (3s Abklingzeit)\nVerkaufspreis:" }
entries[140802] = { ["name"] = "Nachtblühender Wedel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, dass Euch 15 Sek. lang der Effekt 'Rekursive Schläge' gewährt wird, wodurch Eure automatischen Angriffe zusätzlich 20 Schaden verursachen und die Intensität von 'Rekursive Schläge' erhöht wird.\nVerkaufspreis:" }
entries[140803] = { ["name"] = "Etraeus' Himmelskarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Eure Meisterschaft, Euer Tempo oder Euren kritischen Trefferwert für 8 Sek. um 26 zu erhöhen.\nVerkaufspreis:" }
entries[140804] = { ["name"] = "Sternentor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Schadenszauber haben eine Chance, einen Meteor aus dem Wirbelnden Nether herabzurufen, der Eurem Ziel und allen Gegnern in der Nähe 22 Zauberfeuerschaden zufügt.\nVerkaufspreis:" }
entries[140805] = { ["name"] = "Flüchtiges Paradoxon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Euren nächsten Einsatz eines direkten Heilzaubers 10 Mana wiederherstellen zu lassen, anstatt Mana zu kosten.\nVerkaufspreis:" }
entries[140806] = { ["name"] = "Konvergenz der Schicksale", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe haben eine Chance, die verbleibende Abklingzeit einer Eurer mächtigen Fähigkeiten um 3 Sek. zu verringern. Gilt nicht für Eure Spezialisierung.\nVerkaufspreis:" }
entries[140807] = { ["name"] = "Höllischer Vertrag", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Verringert sämtlichen erlittenen Schaden 20 Sek. lang um 50%, bis zu maximal [ 985 * (1 + Vielseitigkeit)] verhindertem Schaden. Wenn dieser Effekt abläuft, erleidet Ihr 30 Sek. lang 20% zusätzlichen Schaden als Feuerschaden, bis zu maximal 4197 zusätzlichem Schaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[140808] = { ["name"] = "Destillat der Seelen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Verfällt in eine teuflische Wut und fügt einem zufälligen Gegner in der Nähe 3 Sek. lang alle 0.25 Sek. 34 Schattenschaden zu. Während die Wut anhält, könnt Ihr Euch weder bewegen noch Fähigkeiten einsetzen. (1 Min, 20 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[140809] = { ["name"] = "Flüstern im Dunkel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Schadenszauber haben eine Chance, den Effekt 'Perfider Pakt' auszulösen, der Euer Zaubertempo 12 Sek. lang um 0 % erhöht. Wenn 'Perfider Pakt' abläuft, wird Euer Zaubertempo für 8 Sek. um 0 % verringert. (20s Abklingzeit)\nVerkaufspreis:" }
