entries[141040] = { ["name"] = "Technik: Glyphe 'Wildes Chamäleon'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Wildes Chamäleon' herstellt.\nStellt eine Glyphe 'Wildes Chamäleon' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Wildes Chamäleon'\nKlassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Katzengestalt annehmt, wird Eure verwandelte Gestalt zufällig ausgewählt.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)" }
entries[141041] = { ["name"] = "Technik: Glyphe 'Waldpfad'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe 'Waldpfad' herstellt.\nStellt eine Glyphe 'Waldpfad' her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGlyphe 'Waldpfad'\nKlassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Spurt' hinterlässt nun eine Spur von Blättern.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)" }
