entries[141045] = { ["name"] = "Veraltete Technik", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\n\"Es sieht zwar aus, als wäre dieses Rezept entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
