entries[141216] = { ["name"] = "Entweihte Zügel", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen reitbaren Entweiher des Hains beschwört.\nBeschwört einen reitbaren Entweiher des Hains oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Wächter des Hains des Smaragdgrünen Traums fielen als Erste dem verderblichen Einfluss des Alptraums zum Opfer.\"\nErfolg:\nRuhm des Schlachtzüglers von Legion\nKategorie:\nDungeons & Schlachtzüge" }
entries[141217] = { ["name"] = "Zügel des Leyfederhippogryphen", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren Leyfederhippogryphen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese uralten Reittiere der Hochgeborenen streifen jetzt wild über die Verheerten Inseln, lassen sich aber aufgrund ihrer latenten magischen Kräfte nur schwer aufspüren.\"\nErfolg:\nRuhm des Helden von Legion\nKategorie:\nDungeons & Schlachtzüge" }
